// Address mapping for AE350

#ifndef __AE350_H
#define __AE350_H

// ---------------------------------------
// Trap Context structure
// ---------------------------------------
typedef struct
{
  union
  {
    struct
    {
      long x0;
      long x1;
      long x2;
      long x3;
      long x4;
      long x5;
      long x6;
      long x7;
      long x8;
      long x9;
      long x10;
      long x11;
      long x12;
      long x13;
      long x14;
      long x15;

// rt_all_gprs.S
//
// Tier-1 fixture: full sweep of x1..x31 across the QEMU1 -> vsim handoff.
// Each register survives the round-trip with its 64-bit value intact.
//
// Phase A (QEMU1):
//   x5 = 0x00002000 (also serves as Phase C spill base).
//   x_i = 0xA000_0000_0000_0000 + i for i in {1..4, 6..31}.
// Phase B (vsim):  no-op.
// Phase C (standalone-run self-verify tail):
//   Spill x6, x28, x29 (sacrificed below).
//   Verify x_i directly for i in {1..4, 7..27, 30..31, then 5}.
//   Verify spilled x6, x28, x29 against expected.
//   Exit code = first mismatching reg num, or 0 on full pass.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    li      x6, 0xA000000000000000   // temp base for ADDI sweep
    addi    x1,  x6, 1
    addi    x2,  x6, 2
    addi    x3,  x6, 3
    addi    x4,  x6, 4
    addi    x7,  x6, 7
    addi    x8,  x6, 8
    addi    x9,  x6, 9
    addi    x10, x6, 10
    addi    x11, x6, 11
SEP
// rt_sign_bits.S
//
// Tier-1 fixture: 64-bit width fidelity through DM Abstract Commands.
// A bug that truncates or sign-extends incorrectly between the 32-bit
// data0/data1 halves would corrupt the high bits.
//
// Phase A (QEMU1): seed x10..x14 with edge-case 64-bit constants.
// Phase B (vsim):  no-op (just bridges trigger entry/exit).
// Phase C (standalone-run self-verify): each value; exit code = first mismatching reg num,
//                  or 0 on full pass.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    li      x10, 0
    li      x11, -1
    li      x12, 0x8000000000000000
    li      x13, 0x7FFFFFFFFFFFFFFF
    li      x14, 0x00000000FFFFFFFF

    slti   x0, x0,  0x5A0                 // QEMU1 drains, exits

    slti   x0, x0,  0x5A1                 // vsim drains, exits 200

phase_c:
    bne     x10, x0, fail_x10
    li      t0, -1
    bne     x11, t0, fail_x11
SEP
// Shared exit-via-semihosting macro for hybrid round-trip fixtures.
//
// SEMIHOST_EXIT exit_reg
//   Builds the {reason=ADP_Stopped_ApplicationExit, exit_code=<exit_reg>}
//   16-byte block at 0x00001000, sets a0=SYS_EXIT_EXTENDED (0x20), a1=block,
//   then issues the RISC-V semihosting `slli x0,x0,0x1f; ebreak; srai x0,x0,0x7`
//   triple. exit_reg may be any GPR holding the desired host exit code; this
//   macro clobbers t0, t1, a0, a1.
//
// QEMU's host-exit returns the low 8 bits of <exit_reg> as the process status.

.macro SEMIHOST_EXIT exit_reg
    li      t0, 0x00001000
    li      t1, 0x20026                     // ADP_Stopped_ApplicationExit
    sd      t1, 0(t0)
    sd      \exit_reg, 8(t0)
    li      a0, 0x20                        // SYS_EXIT_EXTENDED
    mv      a1, t0
    .option push
    .option norvc
    slli    x0, x0, 0x1f
    ebreak
    srai    x0, x0, 0x7
    .option pop
99: j       99b
.endm
